var i=`0436-lutefisk`;var n=`world-0436`;var o=`NO`;var r=`northern-europe`;var s=4;var a=4356;var d={en:`Lutefisk`,ua:`Лютефіск`};var l={en:`A traditional dish from Norway, centered on dried stockfish, potato, bacon. A measured home-kitchen version organized by cooking step. Lutefisk-inspired cod dinner only. Genuine lutefisk requires commercially prepared lye-treated stockfish, which is missing from the catalog; do not attempt homemade lye processing.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: сушена риба стокфіш, картопля, бекон. Домашній варіант із кількостями продуктів за етапами приготування. Лише вечеря з тріскою у стилі лютефіск. Для справжнього лютефіску потрібна готова промислово оброблена лугом риба, якої немає в каталозі; самостійно обробляти рибу лугом не слід.`};var u=[{en:`This is not traditional lutefisk. Soak commercially dried stockfish in the refrigerator for several days, changing the water often and following the producer instructions. Never treat fish with lye at home.`,ua:`Це не традиційний лютефіск. Вимочуйте сушену тріску кілька днів у холодильнику з частою зміною води за інструкцією виробника. Ніколи не обробляйте рибу лугом удома.`,t:[`soaking-dried-produce`],m:4320,i:[[`dried-stockfish`,400,`g`],[`water`,1400,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,700,`g`],[`water`,1e3,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 8 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 8 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:8,i:[[`bacon`,180,`g`],[`unsalted-butter`,30,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var h={slug:i,id:n,country:`NO`,region:r,servings:4,minutes:a,title:d,text:l,steps:u};export{o as country,h as default,n as id,a as minutes,r as region,s as servings,i as slug,u as steps,l as text,d as title};